import React from 'react';
import { useParams } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Truck, MapPin, Phone, User, Package, Clock, CheckCircle, Navigation } from 'lucide-react';
import dispatchService from '../../services/dispatchService';
import StatusBadge from '../../components/datadisplay/StatusBadge';

const DispatchDetails = () => {
    const { id } = useParams();

    const { data: dashboard, isLoading } = useQuery({
        queryKey: ['dispatch-dashboard'],
        queryFn: dispatchService.getDashboard
    });

    const assignment = dashboard?.recentAssignments?.find(a => a.id === id);

    if (isLoading) {
        return (
            <div className="flex items-center justify-center py-12">
                <div className="w-8 h-8 border-2 border-teal-500 border-t-transparent rounded-full animate-spin" />
            </div>
        );
    }

    if (!assignment) {
        return (
            <div className="text-center py-12">
                <Package className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-500">Delivery not found</p>
            </div>
        );
    }

    const timeline = [
        { status: 'assigned', label: 'Assigned', icon: Package, done: true },
        { status: 'picked_up', label: 'Picked Up', icon: Truck, done: ['picked_up', 'in_transit', 'delivered'].includes(assignment.status) },
        { status: 'in_transit', label: 'In Transit', icon: Navigation, done: ['in_transit', 'delivered'].includes(assignment.status) },
        { status: 'delivered', label: 'Delivered', icon: CheckCircle, done: assignment.status === 'delivered' }
    ];

    return (
        <div className="max-w-3xl mx-auto space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Delivery Details</h1>
                <p className="text-gray-500 mt-1">Assignment #{assignment.id?.slice(0, 8)}</p>
            </div>

            {/* Status Timeline */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border p-6">
                <h3 className="font-semibold mb-6">Delivery Progress</h3>
                <div className="flex items-center justify-between">
                    {timeline.map((step, index) => (
                        <div key={step.status} className="flex items-center flex-1">
                            <div className="flex flex-col items-center">
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${step.done ? 'bg-teal-500 text-white' : 'bg-gray-200 text-gray-400'
                                    }`}>
                                    <step.icon className="h-5 w-5" />
                                </div>
                                <p className="text-xs mt-2 text-center font-medium">{step.label}</p>
                            </div>
                            {index < timeline.length - 1 && (
                                <div className={`flex-1 h-0.5 mx-2 ${timeline[index + 1].done ? 'bg-teal-500' : 'bg-gray-200'
                                    }`} />
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {/* Delivery Information */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Customer Details */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border p-6"
                >
                    <h3 className="font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
                        <User className="h-5 w-5 text-teal-600" />
                        Customer Information
                    </h3>
                    <div className="space-y-3">
                        <div>
                            <p className="text-sm text-gray-500">Name</p>
                            <p className="font-medium">{assignment.customerFirstName} {assignment.customerLastName}</p>
                        </div>
                        <div className="flex items-center gap-2">
                            <Phone className="h-4 w-4 text-gray-400" />
                            <p className="font-medium">{assignment.customerPhone}</p>
                        </div>
                        <div className="flex items-start gap-2">
                            <MapPin className="h-4 w-4 text-gray-400 mt-0.5" />
                            <div>
                                <p className="font-medium">{assignment.customerAddress}</p>
                                <p className="text-sm text-gray-500">{assignment.customerCity}, {assignment.customerState}</p>
                            </div>
                        </div>
                    </div>
                </motion.div>

                {/* Product & Order Info */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border p-6"
                >
                    <h3 className="font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
                        <Package className="h-5 w-5 text-teal-600" />
                        Product & Order
                    </h3>
                    <div className="space-y-3">
                        <div className="flex items-center gap-3">
                            <div className="h-16 w-16 rounded-lg bg-gray-100 dark:bg-gray-700 flex items-center justify-center overflow-hidden">
                                {assignment.productImage ? (
                                    <img src={assignment.productImage} alt={assignment.productName} className="h-full w-full object-cover" />
                                ) : (
                                    <Package className="h-8 w-8 text-gray-400" />
                                )}
                            </div>
                            <div>
                                <p className="font-medium">{assignment.productName}</p>
                                <StatusBadge status={assignment.status} size="sm" />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-3 pt-3 border-t">
                            <div>
                                <p className="text-sm text-gray-500">Delivery Fee</p>
                                <p className="font-bold text-teal-600">${assignment.deliveryFee?.toFixed(2) || '0.00'}</p>
                            </div>
                            <div>
                                <p className="text-sm text-gray-500">Order Amount</p>
                                <p className="font-bold">${assignment.orderAmount?.toFixed(2) || '0.00'}</p>
                            </div>
                        </div>
                    </div>
                </motion.div>
            </div>

            {/* Time Information */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border p-6"
            >
                <h3 className="font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
                    <Clock className="h-5 w-5 text-teal-600" />
                    Timeline
                </h3>
                <div className="space-y-3">
                    {assignment.pickupTime && (
                        <div className="flex items-center gap-3">
                            <div className="w-2 h-2 rounded-full bg-teal-500" />
                            <div>
                                <p className="font-medium">Picked Up</p>
                                <p className="text-sm text-gray-500">{new Date(assignment.pickupTime).toLocaleString()}</p>
                            </div>
                        </div>
                    )}
                    {assignment.deliveryTime && (
                        <div className="flex items-center gap-3">
                            <div className="w-2 h-2 rounded-full bg-emerald-500" />
                            <div>
                                <p className="font-medium">Delivered</p>
                                <p className="text-sm text-gray-500">{new Date(assignment.deliveryTime).toLocaleString()}</p>
                            </div>
                        </div>
                    )}
                    <div className="flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-gray-400" />
                        <div>
                            <p className="font-medium">Created</p>
                            <p className="text-sm text-gray-500">{new Date(assignment.createdAt).toLocaleString()}</p>
                        </div>
                    </div>
                </div>
            </motion.div>
        </div>
    );
};

export default DispatchDetails;
